package com.jmk.predictionfoot;
import android.app.*; import android.os.*; import android.graphics.Color; import android.graphics.Typeface; import android.view.*; import android.widget.*; import org.json.*;
public class AnalysisActivity extends Activity{
 LinearLayout box; int dp(float x){return(int)(x*getResources().getDisplayMetrics().density+.5f);} TextView t(String s,int z,boolean b){TextView v=new TextView(this);v.setText(s);v.setTextColor(Color.WHITE);v.setTextSize(z);v.setPadding(dp(4),dp(7),dp(4),dp(7));if(b)v.setTypeface(Typeface.DEFAULT,Typeface.BOLD);return v;}
 public void onCreate(Bundle b){super.onCreate(b);box=new LinearLayout(this);box.setOrientation(LinearLayout.VERTICAL);box.setPadding(dp(16),dp(14),dp(16),dp(14));box.setBackgroundColor(Color.rgb(7,17,31));setContentView(new ScrollView(this){{addView(box);}});long id=getIntent().getLongExtra("fixture",0);box.addView(t("Analyse du match",24,true));box.addView(t(getIntent().getStringExtra("home")+"  vs  "+getIntent().getStringExtra("away"),18,true));box.addView(t("Fixture ID : "+id,12,false));box.addView(t("Chargement des statistiques…",15,false));new Thread(()->{try{JSONObject j=ApiClient.get("/api/analyze?fixture="+id);runOnUiThread(()->show(j));}catch(Exception e){runOnUiThread(()->showError(e.getMessage()));}}).start();}
 void showError(String e){box.addView(t("Analyse indisponible : "+e,15,false));}
 void show(JSONObject j){box.removeViews(3,box.getChildCount()-3);box.addView(t("Résultat de l'analyse",19,true));String[] keys={"prediction","1x2","btts","over_1_5","over_2_5","over_3_5","exact_scores","classement","forme","statistiques"};for(String k:keys){if(j.has(k))box.addView(t(k.toUpperCase()+"\n"+j.optString(k),15,false));}if(j.has("ok")&&!j.optBoolean("ok"))box.addView(t(j.optString("erreur","Erreur"),15,false));}
}
